```python
def ucb1(self) -> float:
        """UCB1 score for selection."""
        if self.visits == 0:
            return float('inf')
        if self.parent is None or self.parent.visits == 0:
            return self.q_value
        exploration = math.sqrt(2.0 * math.log(self.parent.visits) / self.visits)
        return self.q_value + 1.414 * exploration
