def binary_search(arr: List[int], target: int) -> Optional[int]:
    \"\"\"Cari target dalam sorted array. Return index atau None.\"\"\"
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return None
