def rlc_bandpass(R: float, L: float, C: float) -> Dict[str, float]:
        """Band-pass RLC: f0, bandwidth, Q factor."""
        f0 = 1.0 / (2 * math.pi * math.sqrt(L * C))
        BW = R / (2 * math.pi * L)
