def _extract_function_name(self, code: str) -> Optional[str]:
        """Ekstrak nama fungsi pertama yang didefinisikan dalam kode."""
        try:
            tree = ast.parse(code)
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    return node.name
        except SyntaxError:
            # Coba regex fallback
            m = re.search(r'def\s+(\w+)\s*\(', code)
            if m:
                return m.group(1)
        return None
