def feed(self, token: str) -> str:
        self.buffer += token
        out = ""
        while self.buffer:
            if self.in_thinking:
                idx = self.buffer.find("</think>")
                if idx != -1:
                    self.buffer = self.buffer[idx + 8:]
                    self.in_thinking = False
                else:
                    has_partial = False
                    for i in range(7, 0, -1):
                        if "</think>".startswith(self.buffer[-i:]):
                            self.buffer = self.buffer[-i:]
                            has_partial = True
                            break
                    if not has_partial:
                        self.buffer = ""
                    break
            else:
                idx = self.buffer.find("<think>")
                if idx != -1:
                    out += self.buffer[:idx]
                    self.buffer = self.buffer[idx + 7:]
                    self.in_thinking = True
                else:
                    has_partial = False
                    for i in range(6, 0, -1):
                        if "<think>".startswith(self.buffer[-i:]):
                            out += self.buffer[:-i]
                            self.buffer = self.buffer[-i:]
                            has_partial = True
                            break
                    if not has_partial:
                        out += self.buffer
                        self.buffer = ""
                    break
        return out
