```python
def find_gguf_path(model_tag: str, override_path: str = "") -> str:
    """
    Melacak letak file GGUF model.

    Prioritas:
    1. override_path (Direct GGUF Mode) — jika path valid, langsung digunakan tanpa Ollama.
    2. Manifest Ollama (fallback) — untuk kompatibilitas mundur.
    """
    # === DIRECT GGUF MODE ===
    if override_path:
        gguf_file = Path(override_path)
        if gguf_file.exists() and gguf_file.stat().st_size > 0:
            print(f"[MOKO INFERENCE] Direct GGUF Mode: menggunakan {gguf_file.name} ({gguf_file.stat().st_size // 1024 // 1024} MB)")
            return str(gguf_file)
        else:
            print(f"[MOKO INFERENCE] PERINGATAN: GGUF path '{override_path}' tidak ditemukan atau kosong. Fallback ke Ollama...")

    # === FALLBACK: OLLAMA MANIFEST LOOKUP ===
    try:
        from moko_memory.ramdisk import get_ollama_models_path
        models_path = Path(get_ollama_models_path())
    except Exception:
        raise FileNotFoundError("Ollama models path tidak tersedia dan direct GGUF path tidak dikonfigurasi.")

    # 1. Parsing tag (misal: huihui_ai/qwen2.5-1m-abliterated:7b)
    if ":" in model_tag:
        name, tag = model_tag.split(":", 1)
    else:
        name, tag = model_tag, "latest"

    # Jika nama tidak mengandung slash, asumsikan model library (misal: library/name)
    if "/" not in name:
        name = f"library/{name}"

    # Path manifest: registry.ollama.ai/<name>/<tag>
    manifest_path = models_path / "manifests" / "registry.ollama.ai" / name / tag

    # Jika tidak ditemukan di path ramdisk (mungkin belum disalin/warmup), gunakan SSD
    if not manifest_path.exists():
        ssd_manifest = Path("/home/brianatmokoo/.ollama/models") / "manifests" / "registry.ollama.ai" / name / tag
        if ssd_manifest.exists():
            manifest_path = ssd_manifest
        else:
            raise FileNotFoundError(f"Manifest tidak ditemukan untuk model '{model_tag}' di: {manifest_path} atau {ssd_manifest}")

    with open(manifest_path, "r") as f:
        manifest = json.load(f)

    for layer in manifest.get("layers", []):
        if layer.get("mediaType") == "application/vnd.ollama.image.model":
            digest = layer.get("digest")
            if digest.startswith("sha256:"):
                digest_val = digest.split(":", 1)[1]
                # Cari blob di folder active models path
                blob_path = manifest_path.parent.parent.parent.parent.parent / "blobs" / f"sha256-{digest_val}"
                if blob_path.exists():
                    return str(blob_path)
                # Fallback ke SSD blobs jika di RAM disk tidak ada
                ssd_blob = Path("/home/brianatmokoo/.ollama/models/blobs") / f"sha256-{digest_val}"
                if ssd_blob.exists():
                    return str(ssd_blob)
                raise FileNotFoundError(f"File blob tidak ditemukan untuk digest: {digest} di {blob_path} atau {ssd_blob}")

    raise ValueError(f"Tidak ada layer model GGUF di manifest untuk {model_tag}")
