def extract_thoughts(self, text: str) -> str:
        outside = re.sub(r'<thought>.*?</thought>', '', text, flags=re.DOTALL).strip()
        inside = re.findall(r'<thought>(.*?)</thought>', text, flags=re.DOTALL)
        if outside and len(outside.strip()) > 20:
