```cpp
void MemoryEdgeItem::paint(QPainter* painter, const QStyleOptionGraphicsItem* option, QWidget* widget) {
{
    Q_UNUSED(option);
    Q_UNUSED(widget);
    if (!m_source || !m_dest) return;

    painter->setRenderHint(QPainter::Antialiasing);

    QColor color = m_source->m_color;
    if (m_isCrossDomain) {
        color = QColor(255, 107, 53, 110); // Amber orange with medium transparency
    }

    if (m_highlighted) {
        color = QColor(0, 255, 136); // Glowing neon green
    } else if (!m_isCrossDomain) {
        color.setAlpha(60); // Semi-transparent for normal tree hierarchy
    }

    QPen pen(color, m_highlighted ? 2.5 : m_isCrossDomain ? 1.5 : 1.0);
    if (m_isCrossDomain) {
        pen.setStyle(Qt::DashLine);
    }
    painter->setPen(pen);

    // Draw Bezier curved path instead of straight line to simulate natural nerve threads
    QPointF p1 = m_source->pos();
    QPointF p2 = m_dest->pos();
    QPointF mid = (p1 + p2) / 2.0;
    QPointF diff = p2 - p1;
    double length = std::sqrt(diff.x()*diff.x() + diff.y()*diff.y());
    QPointF normal(0.0, 0.0);
    if (length > 0.1) {
        double offsetMagnitude = length * 0.12; // 12% curvature
        normal = QPointF(-diff.y() / length, diff.x() / length) * offsetMagnitude;
    }
    QPointF ctrl = mid + normal;

    QPainterPath path;
    path.moveTo(p1);
    path.quadTo(ctrl, p2);

    painter->drawPath(path);
}
